import { PieChart } from "march/charts"
import { Button } from "march/ui"

// pizza paylaşımı: her "dilim al" düğmesi o kişinin payını büyütür, ortada kalan dilim sayısı yazar
const PEOPLE = ["Ece", "Can", "Deniz"]

export function PizzaSlices() {
  let $eaten = [1, 1, 1]
  const left = () => 8 - $eaten.reduce((a, b) => a + b, 0)
  const take = (i: number) => { if (left() > 0) $eaten = $eaten.map((v, j) => (j === i ? v + 1 : v)) }
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap"], gap: 2 }}>
      {PEOPLE.map((p, i) => <Button size="sm" on:click={() => take(i)} disabled={() => left() === 0}>{p} dilim al 🍕</Button>)}
    </div>
    <PieChart data={() => [...PEOPLE.map((label, i) => ({ label, value: $eaten[i] })), { label: "Kalan", value: left() }]}
      donut center={left() ? `${left()} dilim kaldı` : "Bitti!"} animate legend="right" title="Pizza" height={220} />
  </div>
}

import { PieChart } from "march/charts"
import { Card, Segmented } from "march/ui"

// sitenin trafik kaynakları: hafta ya da ay seçilir, dilimler yeni paylarına döner; bir dilime tıklamak onu süzer
const DATA: Record<string, { label: string; value: number }[]> = {
  week: [{ label: "Arama", value: 4200 }, { label: "Doğrudan", value: 2100 }, { label: "Sosyal", value: 1800 }, { label: "E-posta", value: 640 }],
  month: [{ label: "Arama", value: 16400 }, { label: "Doğrudan", value: 9800 }, { label: "Sosyal", value: 11200 }, { label: "E-posta", value: 3100 }],
}

export function TrafficSources() {
  let $range = "week"
  let $source = "Hepsi"
  return <Card title="Trafik kaynakları" actions={[<Segmented size="sm" bind:value={$range} aria-label="Dönem" options={[{ value: "week", label: "Bu hafta" }, { value: "month", label: "Bu ay" }]} />]}>
    <PieChart data={() => DATA[$range]} donut={0.7} padAngle={0.02} format="compact" animate="out" legend="bottom" title="Trafik kaynakları"
      onSelect={(p: { label: unknown; share: number }) => { $source = String(p.label) }} height={240} />
    <p sx={{ text: "sm", color: "muted" }}>Süzgeç: {() => $source}</p>
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { PieChartLab } from "./PieChartLab.tsx"

// PieChartLab'in testleri: kaydedince Testler sekmesinde çalışır
test("dört kalem dört dilim; ortada kendi yazısı", () => {
  const s = renderTest(() => <PieChartLab />)
  const pie = s.get(".lab-pie")!
  expect(pie.querySelectorAll(".m-chart-slice").length).toBe(4)
  expect(pie.querySelector(".m-chart-center")!.textContent).toBe("4 kalem")
})

test("bir dilime tıklamak onu payıyla seçer", async () => {
  const s = renderTest(() => <PieChartLab />)
  s.get(".lab-pie .m-chart-slice")!.dispatchEvent(new MouseEvent("click", { bubbles: true }))
  await s.flush()
  expect(s.get(".lab-picked")!.textContent).toContain("Kira")
})

test("veri boşalınca boş metni görünür", async () => {
  const s = renderTest(() => <PieChartLab />)
  await s.click(".lab-empty")
  expect(s.sees("Harcama yok")).toBe(true)
})

test("düz pastanın ortası yok", () => {
  const s = renderTest(() => <PieChartLab />)
  expect(s.get(".lab-plain .m-chart-center")).toBe(null)
})
